-- Generated by Murakumo for duckdb: the project as plain SQL, without dbt.
-- An incremental model: built in full the first time, then only rows past the watermark.
CREATE TABLE IF NOT EXISTS intermediate.sat_customer AS
-- A Data Vault satellite: insert-only. A row is added for a hub_customer_hk when its descriptive
-- columns change (by hashdiff), so every version is kept.

with customer as (

    select * from staging.stg_tpch_erp__customer

),

incoming as (

    select
        MD5(COALESCE(UPPER(TRIM(CAST(CAST(customer.c_custkey AS BIGINT) AS TEXT))), '')) as hub_customer_hk,
        cast(customer.c_custkey as BIGINT) as customer_number,
        cast(customer.c_name as VARCHAR) as customer_name,
        cast(customer.c_mktsegment as VARCHAR) as market_segment,
        cast(customer.c_acctbal as DECIMAL(18,4)) as account_balance,
        MD5(COALESCE(UPPER(TRIM(CAST(CAST(customer.c_name AS TEXT) AS TEXT))), '') || '||' || COALESCE(UPPER(TRIM(CAST(CAST(customer.c_mktsegment AS TEXT) AS TEXT))), '') || '||' || COALESCE(UPPER(TRIM(CAST(CAST(customer.c_acctbal AS DECIMAL(18, 4)) AS TEXT))), '')) as hashdiff,
        cast(customer._ingested_at as TIMESTAMPTZ) as load_date,
        'tpch_erp' as record_source
    from customer

),

ranked as (

    select
        incoming.*,
        row_number() over (
            partition by incoming.hub_customer_hk
            order by incoming.load_date desc
        ) as row_in_batch
    from incoming

)

select
    ranked.hub_customer_hk,
    ranked.customer_number,
    ranked.customer_name,
    ranked.market_segment,
    ranked.account_balance,
    ranked.hashdiff,
    ranked.load_date,
    ranked.record_source
from ranked

where ranked.row_in_batch = 1;
-- The rows past the watermark, kept aside while the old versions of them are removed.
DROP TABLE IF EXISTS sat_customer__new;
CREATE TEMPORARY TABLE sat_customer__new AS
-- A Data Vault satellite: insert-only. A row is added for a hub_customer_hk when its descriptive
-- columns change (by hashdiff), so every version is kept.

with customer as (

    select * from staging.stg_tpch_erp__customer

),

incoming as (

    select
        MD5(COALESCE(UPPER(TRIM(CAST(CAST(customer.c_custkey AS BIGINT) AS TEXT))), '')) as hub_customer_hk,
        cast(customer.c_custkey as BIGINT) as customer_number,
        cast(customer.c_name as VARCHAR) as customer_name,
        cast(customer.c_mktsegment as VARCHAR) as market_segment,
        cast(customer.c_acctbal as DECIMAL(18,4)) as account_balance,
        MD5(COALESCE(UPPER(TRIM(CAST(CAST(customer.c_name AS TEXT) AS TEXT))), '') || '||' || COALESCE(UPPER(TRIM(CAST(CAST(customer.c_mktsegment AS TEXT) AS TEXT))), '') || '||' || COALESCE(UPPER(TRIM(CAST(CAST(customer.c_acctbal AS DECIMAL(18, 4)) AS TEXT))), '')) as hashdiff,
        cast(customer._ingested_at as TIMESTAMPTZ) as load_date,
        'tpch_erp' as record_source
    from customer

    where cast(customer._ingested_at as TIMESTAMPTZ) > (select coalesce(max(load_date), cast('1900-01-01' as TIMESTAMPTZ)) from intermediate.sat_customer)

),

ranked as (

    select
        incoming.*,
        row_number() over (
            partition by incoming.hub_customer_hk
            order by incoming.load_date desc
        ) as row_in_batch
    from incoming

)
,

latest as (

    select hub_customer_hk, hashdiff
    from (
        select
            existing.hub_customer_hk,
            existing.hashdiff,
            row_number() over (partition by existing.hub_customer_hk order by existing.load_date desc) as row_in_table
        from intermediate.sat_customer as existing
    ) as versions
    where row_in_table = 1

)

select
    ranked.hub_customer_hk,
    ranked.customer_number,
    ranked.customer_name,
    ranked.market_segment,
    ranked.account_balance,
    ranked.hashdiff,
    ranked.load_date,
    ranked.record_source
from ranked

left join latest
    on latest.hub_customer_hk = ranked.hub_customer_hk

where ranked.row_in_batch = 1

    and (latest.hub_customer_hk is null or latest.hashdiff <> ranked.hashdiff);
INSERT INTO intermediate.sat_customer (hub_customer_hk, customer_number, customer_name, market_segment, account_balance, hashdiff, load_date, record_source)
SELECT hub_customer_hk, customer_number, customer_name, market_segment, account_balance, hashdiff, load_date, record_source FROM sat_customer__new;
DROP TABLE sat_customer__new;
